UPDATE inventory_transfer t SET
    status = 'completed',
    notes = 'เบิกตามใบนับสต๊อกรถ 2 (เทมเพลตเพิ่มสินค้า อรุณ.xlsx)',
    submitted_at = now(), submitted_by = t.created_by,
    approved_at = now(), approved_by = t.created_by,
    dispatched_at = now(), dispatched_by = t.created_by,
    received_at = now(), received_by = t.created_by,
    completed_at = now(), completed_by = t.created_by,
    total_sale_value = (SELECT COALESCE(SUM(line_total),0) FROM inventory_transfer_item WHERE transfer_id = t.id)
 WHERE t.id = 'TR20260813000001';

-- 4) เงื่อนไขที่ต้องเป็นจริงหลังทำงาน
DO $$
DECLARE n bigint;
BEGIN
  SELECT COALESCE(sum(qty),0) INTO n FROM address_master WHERE store_id='store_00001';
  IF n <> 23748 THEN RAISE EXCEPTION 'pos2 ควรมี 23748 ชิ้น แต่ได้ %', n; END IF;
  SELECT count(*) INTO n FROM address_master WHERE store_id='store_00001' AND qty > 0;
